"/* ----------------------------------------------------
   2.5 独立的视差背景与动态元素层 (.parallax-bg-layer)
   ---------------------------------------------------- */
.parallax-bg-layer {
  position: fixed;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;
  z-index: 0; /* 背景图层：位于 body 背景之上、粒子画布之下 */
  will-change: transform;
  transition: transform 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  pointer-events: none;
  overflow: hidden;
}

/* 宽高比自适应容器，确保 clean 背景底图与 4角时钟、天秤 cutouts 保持等比例视口裁剪，实现像素级重合 */
.bg-aspect-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  height: 100%; /* 默认降级方案：撑满父级，防止因浏览器不支持媒体查询导致尺寸坍塌为 0 */
  will-change: transform;
}

/* 移动端 (941/1672 = 0.5628) cover 填充算法 (使用 1.1 倍视口尺寸，以覆盖父级 .parallax-bg-layer 的 110% 视差安全边距) */
@media screen and (max-width: 819px) and (min-aspect-ratio: 941/1672) {
  .bg-aspect-container {
    width: 110vw;
    height: 195.45vw; /* 110vw * (1672/941) */
  }
}
@media screen and (max-width: 819px) and (max-aspect-ratio: 941/1672) {
  .bg-aspect-container {
    height: 110vh;
    width: 61.91vh; /* 110vh * (941/1672) */
  }
}

